// The industries compiled into this build. `virtual:industries` is generated by
// vite.config.ts: all industries by default, or exactly one when DEMO_INDUSTRY is
// set (a "locked" client build that contains no code for the others).
import type { IndustryConfig, IndustryId } from '../core/types';
import { INDUSTRIES as LIST, LOCKED_INDUSTRY as LOCKED } from 'virtual:industries';

export const INDUSTRIES = LIST as IndustryConfig[];

/** Set in a single-industry client build: no gallery and no links to other demos. */
export const LOCKED_INDUSTRY = LOCKED as IndustryId | null;

export function getIndustry(id: string | undefined): IndustryConfig | undefined {
  return INDUSTRIES.find((c) => c.id === id);
}
